"""
Predefined parser functions for KPI start/end points.

These functions can be used as parser_function when building KPIs (start_point
or end_point). Each has the signature expected by Calculator: (file_path, kpi,
search_start_timestamp=None, search_end_timestamp=None, **kwargs).
"""
from __future__ import annotations

import copy
import logging
import re
from datetime import datetime
from pathlib import Path

from taf.ul.oam_kpi_calculations.parsers.file_parser import parse_file
from .parser import (
    SOAPParser,
    matches_param_transition,
    get_managed_objects_from_envelope,
)


def parse_busy_to_ready_transitions(  # noqa: C901
    file_path, kpi, search_start_timestamp=None, search_end_timestamp=None, just_lte=True
):
    """
    Processes a SOAP trace file to detect Tx/Rx managedObject 'state' transitions from BUSY to READY.

    For each envelope in the file, finds "state" transitions (BUSY→READY) for TX/RX links after the optional
    search_start_timestamp and before optional search_end_timestamp. Information about each transition is
    stored inside the provided KPI object. Only managedObjects whose distName starts with "L" are included
    if just_lte is True.

    Args:
        file_path (str or Path): Path to the SOAP XML trace file. The file name is expected in the format
                                 <SERIAL_NUMBER>_<RMOD_ID>.xml for extracting device info.
        kpi: Object where detected transitions and device info will be populated.
        search_start_timestamp (datetime, optional): Ignore transitions before this timestamp.
        search_end_timestamp (datetime, optional): Ignore transitions after this timestamp.
        just_lte (bool, optional): If True, restricts processing only to distNames starting with "L".

    Behavior:
        - Parses the file record by record.
        - For every managedObject matching the filter, logs and updates the corresponding KPI results.
        - Updates kpi.current_result.device_info with radio serial number and RU name extracted from file name.

    Note:
        The function no longer returns a list of results directly. Results and device info are stored in the
        provided KPI object (see taf/ul/oam_kpi_calculations/kpis_definition.py:KPIResult).
    """
    file_name = Path(file_path).name
    match = re.search(r"(?P<SERIAL_NUMBER>[A-Z0-9]+)_(?P<ID>RMOD_\d+)", file_name)
    if match:
        radio_serial_number = match.group("SERIAL_NUMBER")
        runtime_ru_name = match.group("ID").replace("_", "-")
    else:
        raise ValueError(
            "File path does not match the expected format. Expected format: <SERIAL_NUMBER>_<RMOD_ID>. Got: %s",
            file_path,
        )

    if runtime_ru_name not in kpi.dict_results:
        kpi.current_result.clear_result()
        kpi.dict_results[runtime_ru_name] = copy.deepcopy(kpi.current_result)
    current_result = kpi.dict_results[runtime_ru_name]
    current_result.device_info["serial_number"] = radio_serial_number
    logging.info(f"Processing: {file_name} for checking BUSY to READY transitions")
    for record_index, record in enumerate(SOAPParser(file_path).records(), start=1):
        dt = record.timestamp
        if dt is None:
            continue
        if search_start_timestamp is not None and dt < search_start_timestamp:
            continue
        if search_end_timestamp is not None and dt > search_end_timestamp:
            continue

        envelope = record.envelope()
        if envelope is None:
            continue

        all_transitions = _get_tx_rx_link_busy_to_ready_transitions(envelope)
        for tx_rx_dist_name in all_transitions:
            if just_lte and not (tx_rx_dist_name and tx_rx_dist_name[0] == "L"):
                _log_detected_point(
                    kpi_name=kpi.name,
                    message_type="Ignoring non-LTE point entry",
                    file_name=file_name,
                    record_index=record_index,
                    timestamp=dt,
                    ru_name=runtime_ru_name,
                    tx_rx_dist_name=tx_rx_dist_name,
                )
                continue

            _log_detected_point(
                kpi_name=kpi.name,
                message_type="END POINT DETECTED",
                file_name=file_name,
                record_index=record_index,
                timestamp=dt,
                ru_name=runtime_ru_name,
                tx_rx_dist_name=tx_rx_dist_name,
            )
            if tx_rx_dist_name not in current_result.end_point_entries:
                current_result.end_point_entries[tx_rx_dist_name] = []
            current_result.end_point_entries[tx_rx_dist_name].append(dt)


def _log_detected_point(
    kpi_name: str,
    message_type: str,
    file_name: str,
    record_index: int,
    timestamp: datetime,
    ru_name: str,
    tx_rx_dist_name: str,
) -> None:
    """Format and log a SOAP parser debug message in a consistent format."""
    msg = "[{}][{}]\n".format(kpi_name, message_type)
    msg += "\tFile:\t\t{}\n".format(file_name)
    msg += "\tRecord:\t\t{}\n".format(record_index)
    msg += "\tTimestamp:\t{}\n".format(timestamp)
    msg += "\t{} --> {}\n".format(ru_name, tx_rx_dist_name)
    logging.debug(msg)


def _get_tx_rx_link_busy_to_ready_transitions(envelope) -> list[str]:
    """
    Find all Tx/Rx link managedObjects with state BUSY -> READY in this envelope.

    Each returned item is a Tx/Rx link distName string.
    Example: "L100816.RX1_1_5"
    """
    out: list[str] = []
    for mo in get_managed_objects_from_envelope(envelope):
        if (mo.class_value or "") not in ("Tx", "Rx"):
            continue
        if matches_param_transition(
            managed_object=mo,
            operation_name="update_parm",
            parameter_name="state",
            prev_value="BUSY",
            new_value="READY",
        ):
            out.append(mo.dist_name or "")
    return out


# Line must contain: received API_CPRI_STATE_IND_MSG [cpriLink \d+, cpriState B]
# Example: 00 FCT-1011-B-BTSOMex <2026-01-20T10:32:00.539923Z> ... [CpriSyncMonitor:BBMOD_L-1:CONNECTOR_L-4]
# received API_CPRI_STATE_IND_MSG [cpriLink 3, cpriState B]
API_CPRI_STATE_IND_MSG_PATTERN = re.compile(
    r"<(?P<timestamp>[^>]+)>"
    r".*?\[CpriSyncMonitor:(?P<connector>BBMOD_L-\d+:CONNECTOR_L-\d+)\]"
    r".*?received API_CPRI_STATE_IND_MSG \[(?P<cpri_link>cpriLink \d+), cpriState B\]"
)


def parse_api_cpri_state_ind_msg(file_path, bts_info, kpi, search_start_timestamp=None,  # noqa: C901
                                 search_end_timestamp=None) -> list[dict]:
    """
    Parse a log file for API_CPRI_STATE_IND_MSG (cpriState B) and fill KPI end_point_entries.

    Uses the generic file_parser. Each matched row is a dict with keys:
    timestamp, timestamp_dt, connector, cpri_link, raw_line, line_number.
    Timestamps are appended to kpi.current_result.end_point_entries keyed by connector.
    """
    file_name = Path(file_path).name
    logging.info(f"Processing: {file_name} for checking API_CPRI_STATE_IND_MSG")
    results = parse_file(file_path, API_CPRI_STATE_IND_MSG_PATTERN)
    connector_to_rmod_map = get_connector_to_rmod_map(bts_info)
    for row in results:
        ts = row["timestamp"]
        try:
            normalized = ts.replace("Z", "+00:00")
            row["timestamp_dt"] = datetime.fromisoformat(normalized)
        except (ValueError, TypeError):
            row["timestamp_dt"] = None

        dt = row["timestamp_dt"]
        if dt is not None:
            if search_start_timestamp is not None and dt < search_start_timestamp:
                continue
            if search_end_timestamp is not None and dt > search_end_timestamp:
                continue

        key = f"{row['connector']} - {row['cpri_link']}"

        configuration_suffix = _get_configuration_suffix(row.get("connector"))
        rmod_map = connector_to_rmod_map.get(configuration_suffix)
        if rmod_map is None:
            _log_detected_api_cpri_state(
                kpi_name=kpi.name,
                message_type="Ignoring non-connected CONNECTOR",
                file_name=file_name,
                record_index=row.get("line_number"),
                timestamp=row.get("timestamp_dt"),
                connector=row.get("connector"),
                cpr_link=row.get("cpri_link"),
            )
            continue
        runtime_rmod_name = rmod_map.get("runtime_name")
        if runtime_rmod_name not in kpi.dict_results:
            kpi.current_result.clear_result()
            kpi.dict_results[runtime_rmod_name] = copy.deepcopy(kpi.current_result)
        current_result = kpi.dict_results[runtime_rmod_name]

        _log_detected_api_cpri_state(
            kpi_name=kpi.name,
            message_type="START POINT DETECTED",
            file_name=file_name,
            record_index=row.get("line_number"),
            timestamp=row.get("timestamp_dt"),
            connector=row.get("connector"),
            cpr_link=row.get("cpri_link"),
        )
        if key not in current_result.start_point_entries:
            current_result.start_point_entries[key] = []
        current_result.device_info["dist_name"] = rmod_map.get("dist_name")
        current_result.device_info["product_name"] = rmod_map.get("product_name")
        current_result.entity_id = bts_info["id"]["configuration"]
        current_result.start_point_entries[key].append(row["timestamp_dt"])


def _log_detected_api_cpri_state(
    kpi_name: str, message_type: str, file_name: str, record_index: int, timestamp: datetime,
    connector: str, cpr_link: str
) -> None:
    msg = "[{}][{}]\n".format(kpi_name, message_type)
    msg += "\tFile:\t\t{}\n".format(file_name)
    msg += "\tRecord:\t\t{}\n".format(record_index)
    msg += "\tTimestamp:\t{}\n".format(timestamp)
    msg += "\t{} --> {}\n".format(connector, cpr_link)
    logging.debug(msg)


# Connector format: BBMOD_L-<n>:CONNECTOR_L-<m>  ->  configuration suffix: BBMOD-<n>/RF<m>
_CONNECTOR_TO_RF = re.compile(r"BBMOD_L-(?P<bbmod_num>\d+):CONNECTOR_L-(?P<conn_num>\d+)")


def _get_configuration_suffix(connector: str) -> str:
    """
    Translate connector string (e.g. BBMOD_L-1:CONNECTOR_L-1) to configuration path suffix.

    BBMOD_L-1 is translated to BBMOD-1, CONNECTOR_L-1 to RF1.
    The suffix is used to match firstEndPointId[configuration] in cables (e.g. .../BBMOD-1/RF1).

    Args:
        connector: String like "BBMOD_L-1:CONNECTOR_L-1".

    Returns:
        Suffix like "BBMOD-1/RF1".

    Raises:
        ValueError: If connector does not match expected pattern.
    """
    m = _CONNECTOR_TO_RF.search(connector.strip())
    if not m:
        raise ValueError(
            "Connector must match BBMOD_L-<n>:CONNECTOR_L-<m>, got: {!r}".format(connector)
        )
    return "BBMOD-{}/RF{}".format(m.group("bbmod_num"), m.group("conn_num"))


def _get_rmod_configuration_to_product_name(bts_info: dict) -> dict[str, str]:
    """
    Build a mapping RMOD configuration path -> productName from radioModules.

    Args:
        bts_info: BTS info dict containing radioModules.rmod list.

    Returns:
        Dict mapping configuration string (e.g. MRBTS-100816/EQM-1/APEQM-1/RMOD-7) to productName.
    """
    result: dict[str, str] = {}
    radio_modules = bts_info.get("radioModules") or {}
    rmod_list = radio_modules.get("rmod") or []
    for rmod in rmod_list:
        rmod_id = rmod.get("id") or {}
        configuration = rmod_id.get("configuration")
        product_name = rmod.get("productName")
        if configuration and product_name:
            result[configuration] = product_name
    return result


def get_connector_to_rmod_map(bts_info: dict) -> dict[str, dict]:
    """
    Build a mapping BBMOD-<n>/RF<m> -> RMOD-ID from cables.

    Iterates over bts_info["cables"]; for each cable takes the suffix of
    firstEndPointId[configuration] (e.g. BBMOD-1/RF1) as key and the RMOD-ID
    from secondEndPointId[configuration] (e.g. RMOD-1) as value.
    productName is taken from bts_info radioModules by matching second_configuration.

    Args:
        bts_info: BTS info dict containing a "cables" list and "radioModules".

    Returns:
        Dict mapping configuration suffix to dict with runtime, configuration, dist_name, productName.
    """
    _re_bbmod_rf = re.compile(r"BBMOD_R-(?P<bbmod_num>\d+)/RF(?P<rf_num>\d+)")
    _re_rmod = re.compile(r"RMOD_R-(?P<rmod_num>\d+)")
    rmod_config_to_product = _get_rmod_configuration_to_product_name(bts_info)
    result: dict[str, str] = {}
    cables = bts_info.get("cables") or []
    for cable in cables:
        first = cable.get("firstEndPointId") or {}
        first_config = first.get("runtime")
        if first_config is None:
            continue
        m = _re_bbmod_rf.search(first_config)
        if not m:
            continue
        key = "BBMOD-{}/RF{}".format(m.group("bbmod_num"), m.group("rf_num"))

        second = cable.get("secondEndPointId") or {}
        second_runtime = second.get("runtime")
        second_configuration = second.get("configuration")
        if second_runtime is None:
            continue
        m = _re_rmod.search(second_runtime)
        if not m:
            continue
        configuration_name = second_configuration.split("/")[-2]
        config_dist_name = "/".join(second_configuration.split("/")[:-1])
        product_name = rmod_config_to_product.get(config_dist_name)
        result[key] = {
            'runtime_name': "RMOD-{}".format(m.group("rmod_num")),
            'configuration_name': configuration_name,
            'dist_name': config_dist_name,
            'product_name': product_name,
        }
    return result
